/*
 * A138378  Number of embedded coalitions in an n-person game.
 * https://oeis.org/A138378
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = Bell(n+1) - Bell(n)
 * Range:     u8 n <= 5, u16 n <= 8, u32 n <= 14, u64 n <= 24, u128 n <= 41,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*   Bell numbers are generated by the recurrence
 *   Bell(0) = 1
 *   Bell(m+1) = Σ_{k=0..m} C(m,k) * Bell(k)
 *   The function caches values so that repeated calls are fast. */

#include <stdlib.h>

/* Global cache for Bell numbers */
static seq_t *bell = NULL;        /* array of Bell numbers */
static size_t bell_cap = 0;       /* allocated capacity of bell[] */
static idx_t  bell_last = 0;     /* index of the largest Bell number computed */

/* Ensure that Bell numbers up to 'need' are computed and stored in bell[].
 * 'need' is the maximum index required (Bell(need) will be stored).      */
static void ensure_bell(idx_t need)
{
    /* Initialise the cache on first use */
    if (bell == NULL) {
        bell_cap = 1;
        bell = (seq_t *)calloc(bell_cap, sizeof(seq_t));
        if (bell == NULL) exit(EXIT_FAILURE);   /* kernel error */
        bell[0] = 1;             /* Bell(0) = 1 */
        bell_last = 0;
    }

    /* Nothing to do if we already have enough */
    if (need <= bell_last) return;

    /* Grow the storage array if necessary */
    if (bell_cap < (size_t)need + 1) {
        size_t new_cap = bell_cap ? bell_cap * 2 : 16;
        while (new_cap < (size_t)need + 1) new_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(bell, new_cap * sizeof(seq_t));
        if (tmp == NULL) exit(EXIT_FAILURE);
        bell = tmp;
        bell_cap = new_cap;
    }

    /* Compute Bell numbers from bell_last+1 up to 'need' */
    for (idx_t m = bell_last + 1; m <= need; ++m) {
        seq_t sum = 0;
        seq_t coeff = 1;                                   /* C(m-1,0) */
        for (idx_t k = 0; k < m; ++k) {
            sum += coeff * bell[k];
            if (k + 1 < m)                                 /* update to C(m-1,k+1) */
                coeff = coeff * (seq_t)(m - 1 - k) / (seq_t)(k + 1);
        }
        bell[m] = sum;
    }
    bell_last = need;
}

/* Public function to return a(n) = Bell(n+1) - Bell(n)   */
seq_t a(idx_t n)
{
    /* Need Bell(n+1) and Bell(n) */
    ensure_bell(n + 1);
    return bell[n + 1] - bell[n];
}
